import{_ as e,o,c as d,ag as a}from"./chunks/framework.CPvOxTBX.js";const p=JSON.parse('{"title":"Keyboard shortcuts","description":"","frontmatter":{},"headers":[],"relativePath":"guide/keyboard-shortcuts.md","filePath":"guide/keyboard-shortcuts.md","lastUpdated":1794326147000}'),r={name:"guide/keyboard-shortcuts.md"};function n(s,t,i,c,h,l){return o(),d("div",null,t[0]||(t[0]=[a(`<h1 id="keyboard-shortcuts" tabindex="-1">Keyboard shortcuts <a class="header-anchor" href="#keyboard-shortcuts" aria-label="Permalink to &quot;Keyboard shortcuts&quot;">​</a></h1><p>Ciyue&#39;s shortcuts follow the conventions of <a href="https://github.com/xiaoyifang/goldendict-ng" target="_blank" rel="noreferrer">GoldenDict-ng</a>, <a href="https://ebstudio.info/manual/EBWin4/EBWin4.html" target="_blank" rel="noreferrer">EBWin</a> and <a href="https://ebstudio.info/manual/EBMac/index.php" target="_blank" rel="noreferrer">EBMac</a>: the keys you already know from other dictionaries do the same thing here.</p><p>Most of them are <strong>desktop only</strong>, because Flutter on Android has trouble keeping the focus needed to trigger a keyboard shortcut. On Android, apart from a few shortcuts, most cannot activate reliably because the focus gets lost. Fortunately, the Android devices that actually use a keyboard are few — only UMPCs like the GPD Win Max or OneXPlayer running Waydroid, and some Android tablets and phones with a built-in keyboard. And on a UMPC you can use the desktop build anyway.</p><h2 id="two-levels" tabindex="-1">Two levels <a class="header-anchor" href="#two-levels" aria-label="Permalink to &quot;Two levels&quot;">​</a></h2><p>The dictionary shortcuts work in two levels:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Ctrl+\`  /  Ctrl+1…9      Groups: which dictionaries a lookup uses</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        └── Alt+0…9       Dictionaries: which result you are looking at</span></span>
<span class="line"><span>                            Alt+0 = AI explanation, Alt+1…9 = the first nine dictionaries</span></span>
<span class="line"><span>                            Alt+PgUp / Alt+PgDn = previous / next dictionary tab</span></span></code></pre></div><h2 id="looking-up" tabindex="-1">Looking up <a class="header-anchor" href="#looking-up" aria-label="Permalink to &quot;Looking up&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Shortcut</th><th>Action</th></tr></thead><tbody><tr><td><code>Ctrl</code>+<code>F</code></td><td>Move the focus into the search box</td></tr><tr><td><code>Esc</code></td><td>Move the focus into the search box <strong>and select the text in it</strong>, so typing replaces the word; press it again to return to the entry</td></tr><tr><td><code>Enter</code> on a selection</td><td>Look up the selected text (see below)</td></tr><tr><td><code>Ctrl</code>+<code>Enter</code> on a selection</td><td>Look it up in a new tab, the way <code>Ctrl</code>+click does for a link</td></tr></tbody></table><p>The wide window has two search boxes: the one in the left column and the one in the title bar of the entry. <code>Ctrl</code>+<code>F</code> and <code>Esc</code> go to the one you used last, so they follow you around the window instead of always landing on the left one.</p><h3 id="looking-up-a-selection" tabindex="-1">Looking up a selection <a class="header-anchor" href="#looking-up-a-selection" aria-label="Permalink to &quot;Looking up a selection&quot;">​</a></h3><p>Select a word or a phrase in the entry and press <code>Enter</code> to look it up. This is EBWin and EBMac&#39;s behaviour. On Windows and Linux a right click on a word looks it up too; macOS keeps WKWebView&#39;s own menu.</p><p>Selecting and pressing Enter beats double-clicking a single word, because in languages that do not separate words with spaces what a double-click selects is down to luck; and even in a language like English you sometimes meet compound words and phrasal verbs that a double-click cannot catch:</p><table tabindex="0"><thead><tr><th>Language</th><th>Word to look up</th><th>A single click selects the whole word</th></tr></thead><tbody><tr><td>German</td><td><code>Bundesbank</code> within <code>Bundesbankdirektor</code></td><td><code>Bundesbankdirektor</code></td></tr><tr><td>Japanese</td><td><code>日本語</code> within <code>日本語辞典</code></td><td><code>日本語辞典</code></td></tr><tr><td>Chinese</td><td><code>汉语</code> within <code>现代汉语词典</code></td><td><code>现代汉语词典</code></td></tr><tr><td>English</td><td><code>throw away</code></td><td><code>throw</code> or <code>away</code></td></tr></tbody></table><p>On Android, the long-press menu also offers the same lookup next to <em>Copy</em> and <em>Read aloud</em>; right-clicking a word selects it as well, and the menu&#39;s <em>Query</em> item looks up that word.</p><p>On <strong>Windows and Linux</strong>, the entry&#39;s right-click menu is drawn by Ciyue and offers <em>Lookup</em>, <em>Look up in a New Tab</em>, <em>Copy</em> and <em>Read Aloud</em>. Right-clicking a word selects it; clicking inside an existing selection keeps the whole phrase for Copy and for the lookups. <strong>macOS</strong> is unchanged: WKWebView&#39;s own menu also offers the system dictionary services.</p><h2 id="tabs" tabindex="-1">Tabs <a class="header-anchor" href="#tabs" aria-label="Permalink to &quot;Tabs&quot;">​</a></h2><p>Ciyue has three kinds of tabs, and they are easy to mix up.</p><h3 id="word-tabs" tabindex="-1">Word tabs <a class="header-anchor" href="#word-tabs" aria-label="Permalink to &quot;Word tabs&quot;">​</a></h3><p>The browser-like tabs at the top hold one word each.</p><table tabindex="0"><thead><tr><th>Shortcut</th><th>Action</th></tr></thead><tbody><tr><td><code>Ctrl</code>+<code>T</code></td><td>Open a new tab</td></tr><tr><td><code>Ctrl</code>+<code>W</code></td><td>Close the current tab</td></tr><tr><td><code>Ctrl</code>+<code>Tab</code></td><td>Go to the next tab</td></tr><tr><td><code>Ctrl</code>+<code>Shift</code>+<code>Tab</code></td><td>Go to the previous tab</td></tr><tr><td><code>Ctrl</code>+<code>PgDn</code> / <code>Ctrl</code>+<code>PgUp</code></td><td>Go to the next / previous tab</td></tr></tbody></table><p>When the entry was opened from a word list, <code>←</code> / <code>→</code> move to the previous / next word. This holds on the desktop too, not only in the full-screen list on mobile.</p><h3 id="dictionary-groups" tabindex="-1">Dictionary groups <a class="header-anchor" href="#dictionary-groups" aria-label="Permalink to &quot;Dictionary groups&quot;">​</a></h3><p>A group decides which dictionaries a lookup uses. The groups are listed in the menu at the top of the window, in the order they were created, and the shortcuts follow that order.</p><table tabindex="0"><thead><tr><th>Shortcut</th><th>Action</th></tr></thead><tbody><tr><td><code>Ctrl</code> + backquote</td><td>Switch to the first group, the default one</td></tr><tr><td><code>Ctrl</code>+<code>1</code> … <code>Ctrl</code>+<code>9</code></td><td>Switch to the second to the tenth group</td></tr></tbody></table><p>A number that names no group does nothing. After the switch, the word on screen is looked up again with the dictionaries of the new group.</p><h3 id="dictionary-tabs" tabindex="-1">Dictionary tabs <a class="header-anchor" href="#dictionary-tabs" aria-label="Permalink to &quot;Dictionary tabs&quot;">​</a></h3><p>When the dictionary switch style is <strong>Tabs</strong>, every dictionary gets a tab in the entry. The numbers pick one of them.</p><table tabindex="0"><thead><tr><th>Shortcut</th><th>Action</th></tr></thead><tbody><tr><td><code>Alt</code>+<code>1</code> … <code>Alt</code>+<code>9</code></td><td>Show the first to the ninth dictionary</td></tr><tr><td><code>Alt</code>+<code>0</code></td><td>Show the AI explanation, when it is enabled</td></tr><tr><td><code>Alt</code>+<code>PgUp</code></td><td>Show the previous dictionary tab</td></tr><tr><td><code>Alt</code>+<code>PgDn</code></td><td>Show the next dictionary tab</td></tr></tbody></table><p>Stepping wraps around at either end, the way word tabs do with <code>Ctrl</code>+<code>Tab</code>. The AI tab is part of the cycle when the explanation is enabled, and stepping reaches dictionaries past the ninth, which the number keys cannot name.</p><p>In the <strong>Expansion</strong> style there are no such tabs, and these keys do nothing at all.</p><h2 id="reading" tabindex="-1">Reading <a class="header-anchor" href="#reading" aria-label="Permalink to &quot;Reading&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Shortcut</th><th>Action</th></tr></thead><tbody><tr><td><code>Ctrl</code>+<code>R</code></td><td>Read the word aloud — or stop it when it is already playing</td></tr><tr><td><code>Ctrl</code>+<code>Shift</code>+<code>S</code></td><td>Stop the playback</td></tr><tr><td><code>Alt</code>+<code>↑</code> / <code>Alt</code>+<code>↓</code></td><td>Pick the previous / next entry in the history</td></tr><tr><td><code>Alt</code>+<code>←</code> / <code>Alt</code>+<code>→</code></td><td>Go back / forward through the history of the entry</td></tr><tr><td><code>PgDn</code> / <code>PgUp</code></td><td>Page through the entry, in the expansion layout</td></tr></tbody></table><h2 id="zooming-the-entry" tabindex="-1">Zooming the entry <a class="header-anchor" href="#zooming-the-entry" aria-label="Permalink to &quot;Zooming the entry&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Shortcut</th><th>Action</th></tr></thead><tbody><tr><td><code>Ctrl</code>+= / <code>Ctrl</code>++</td><td>Enlarge the entry</td></tr><tr><td><code>Ctrl</code>+-</td><td>Shrink the entry</td></tr><tr><td><code>Ctrl</code>+<code>0</code></td><td>Back to the normal size</td></tr></tbody></table><p>Only the entry is scaled, the rest of the window keeps its size. The level is remembered between restarts, and <a href="/Ciyue/guide/appearance.html">Appearance</a> has a slider for it.</p><p><code>Ctrl</code>+= and <code>Ctrl</code>++ are the same key on most keyboards; both are bound, so either works.</p><h2 id="other-pages" tabindex="-1">Other pages <a class="header-anchor" href="#other-pages" aria-label="Permalink to &quot;Other pages&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Shortcut</th><th>Action</th><th>Where</th></tr></thead><tbody><tr><td><code>Ctrl</code>+<code>Enter</code></td><td>Translate the text</td><td>Translation</td></tr><tr><td><code>Ctrl</code>+<code>Enter</code></td><td>Check the text</td><td>Writing Check</td></tr><tr><td><code>Space</code></td><td>Show the answer</td><td>Flashcards</td></tr><tr><td><code>1</code> … <code>4</code></td><td>Rate the card</td><td>Flashcards</td></tr></tbody></table><h2 id="mouse-gestures-desktop" tabindex="-1">Mouse gestures (desktop) <a class="header-anchor" href="#mouse-gestures-desktop" aria-label="Permalink to &quot;Mouse gestures (desktop)&quot;">​</a></h2><p>Two mouse gestures switch tabs while reading an entry. <strong>Settings → Other</strong> lets each gesture be assigned its own action: off, switch dictionary tabs, or switch word tabs.</p><table tabindex="0"><thead><tr><th>Gesture</th><th>How</th><th>Default action</th></tr></thead><tbody><tr><td>Rocker</td><td>Hold the <strong>left</strong> button and click the <strong>right</strong> one</td><td>Next dictionary tab</td></tr><tr><td>Wheel</td><td>Hold the <strong>left</strong> button and scroll up / down</td><td>Previous / next word tab</td></tr></tbody></table><p>Both gestures start by holding the left button: clicking the right one is a rocker, scrolling is a wheel gesture, and the two do not conflict. The left button is used instead of the middle one because the middle button is usually the wheel itself — holding it down while scrolling is awkward.</p><p>Rocker only has this one direction: dictionary tabs wrap around, so a few presses cycle back to the start. The wheel gesture is bidirectional, which suits moving back and forth through a longer list of word tabs.</p><p>In the <strong>Expansion</strong> style there are no dictionary tabs, so that action falls back to switching word tabs instead of doing nothing.</p><ul><li>Windows, Linux and macOS only; Android has no right button or wheel.</li><li>Only a right click while the left button is held counts as a gesture, and it does not open a menu. An ordinary right click opens Ciyue&#39;s own menu on Windows and Linux, and the system menu on macOS. On macOS <code>Ctrl</code>+left click is a system-level right click and is excluded from the gesture.</li><li>Wheel events are throttled so one physical scroll does not jump several tabs, and the page&#39;s own scrolling is stopped while the left button is held.</li><li>The click that follows a gesture is swallowed, so it cannot open a dictionary link by accident.</li></ul><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li>The group and dictionary tab shortcuts only act while an entry is on screen.</li><li>On a keyboard where the window manager takes <code>Alt</code>+a number, the dictionary tabs cannot be reached that way.</li><li><code>Ctrl</code>+<code>PgUp</code> and <code>Ctrl</code>+<code>PgDn</code> change the word tab, while <code>Alt</code>+<code>PgUp</code> and <code>Alt</code>+<code>PgDn</code> change the dictionary tab; the same keys without a modifier scroll the entry in the expansion layout.</li><li>Shortcuts with a modifier also fire while the entry&#39;s native WebView holds the focus, regardless of which control is focused. Bare <code>PgUp</code> / <code>PgDn</code> still belong to the entry&#39;s scrolling and to text fields.</li><li>History navigation uses only <code>Alt</code>+<code>↑</code> / <code>↓</code>: macOS Mission Control takes <code>Ctrl</code>+<code>↑</code> / <code>↓</code>, while window tiling on KDE, GNOME and Windows takes <code>Super</code> / <code>Win</code>+<code>↑</code> / <code>↓</code>. <code>Alt</code> is the pair every mainstream desktop leaves free. Inside a macOS text field <code>Option</code>+<code>↑</code> / <code>↓</code> moves to the paragraph start / end, so Ciyue yields to the field while it has the focus.</li><li>On the desktop layout the arrow keys move the keyboard focus between controls; <code>Enter</code> or <code>Space</code> activates the focused one.</li></ul>`,47)]))}const b=e(r,[["render",n]]);export{p as __pageData,b as default};
